def choose_move(observation):
    px, py = observation['self_position']
    width, height = observation['grid_width'], observation['grid_height']
    resources = observation.get('resources', [])
    obstacles = set(observation.get('obstacles', []))
    opponent_x, opponent_y = observation.get('opponent_position', (px, py))
    remaining = observation.get('remaining_resource_count', 0)
    scores = observation.get('scores', {})
    def dist(a, b): return abs(a[0]-b[0])+abs(a[1]-b[1])
    target = None
    min_d = float('inf')
    for res in resources:
        d = dist((px, py), res)
        if d < min_d:
            min_d = d
            target = res
    def move_towards(target_pos):
        dx = target_pos[0] - px
        dy = target_pos[1] - py
        dx = (dx > 0) - (dx < 0)
        dy = (dy > 0) - (dy < 0)
        return dx, dy
    def safe_move(dx, dy):
        nx, ny = px + dx, py + dy
        if 0 <= nx < width and 0 <= ny < height and (nx, ny) not in obstacles:
            return dx, dy
        # fallback to no move
        return 0, 0
    if target:
        dx, dy = move_towards(target)
        return safe_move(dx, dy)
    else:
        # no resources, move towards opponent to challenge
        dx, dy = move_towards((opponent_x, opponent_y))
        return safe_move(dx, dy)
